from ortools.sat.python import cp_model
import json

jobs_data = [  # (machine_id, duration)
    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

model = cp_model.CpModel()

num_jobs = len(jobs_data)
all_machines = set()
for job in jobs_data:
    for machine, _ in job:
        all_machines.add(machine)
num_machines = len(all_machines)

# Compute horizon (upper bound on makespan)
horizon = 0
for job in jobs_data:
    for _, duration in job:
        horizon += duration

# Variables: start times and end times for each task
task_starts = {}
task_ends = {}
task_intervals = {}

for job_id, job in enumerate(jobs_data):
    for task_id, (machine, duration) in enumerate(job):
        start_var = model.NewIntVar(0, horizon, f'start_{job_id}_{task_id}')
        end_var = model.NewIntVar(0, horizon, f'end_{job_id}_{task_id}')
        interval_var = model.NewIntervalVar(start_var, duration, end_var, f'interval_{job_id}_{task_id}')
        task_starts[(job_id, task_id)] = start_var
        task_ends[(job_id, task_id)] = end_var
        task_intervals[(job_id, task_id)] = (interval_var, machine, duration)

# Add precedence constraints inside each job
for job_id, job in enumerate(jobs_data):
    for task_id in range(len(job) - 1):
        model.Add(task_starts[(job_id, task_id + 1)] >= task_ends[(job_id, task_id)])

# Add machine constraints: no overlapping tasks on the same machine
for machine in all_machines:
    intervals = []
    for (job_id, task_id), (interval_var, m, _) in task_intervals.items():
        if m == machine:
            intervals.append(interval_var)
    model.AddNoOverlap(intervals)

# Makespan variable
makespan = model.NewIntVar(0, horizon, 'makespan')
# Makespan is max of all task ends
all_ends = [task_ends[(job_id, len(job) - 1)] for job_id, job in enumerate(jobs_data)]
model.AddMaxEquality(makespan, all_ends)

# Objective: minimize makespan
model.Minimize(makespan)

solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'makespan': solver.Value(makespan)
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

