import json

X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

model = cp_model.CpModel()

# Create variables for each cell that is X (-1), 1 if mine, 0 if safe
mines = {}
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] == X:
            mines[(r, c)] = model.NewBoolVar(f'mine_{r}_{c}')

# Helper to get neighbors of a cell
def neighbors(r, c):
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not (nr == r and nc == c):
                    yield nr, nc

# Add constraints for each cell with a clue (0-8)
for r in range(rows):
    for c in range(cols):
        clue = game_data[r][c]
        if clue >= 0:
            # Sum of mines in neighbors must be equal to clue
            neighbor_vars = []
            for nr, nc in neighbors(r, c):
                if game_data[nr][nc] == X:
                    neighbor_vars.append(mines[(nr, nc)])
                elif game_data[nr][nc] == -1:
                    # Should not happen, but just in case
                    pass
                else:
                    # Known safe cell, no mine
                    pass
            model.Add(sum(neighbor_vars) == clue)

# Solve model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = []
    for r in range(rows):
        row_mines = []
        for c in range(cols):
            if game_data[r][c] == X:
                row_mines.append(solver.Value(mines[(r, c)]))
            else:
                # Known safe cell, no mine
                row_mines.append(0)
        solution.append(row_mines)
    print(json.dumps({'mines': solution}, indent=4))
else:
    print("No solution found.")
