from ortools.sat.python import cp_model
import json

n = 13  # Number of balls
c = 3   # Number of boxes

model = cp_model.CpModel()

# Variables: M[i][j] = 1 if ball i+1 is in box j+1
M = []
for i in range(n):
    row = []
    for j in range(c):
        row.append(model.NewBoolVar(f'M_{i+1}_{j+1}'))
    M.append(row)

# Constraint: Each ball must be in exactly one box
for i in range(n):
    model.Add(sum(M[i][j] for j in range(c)) == 1)

# Constraint: For each triple (x,y,z) with x + y = z, no triple in same box
# Find all triples with x + y = z, 1 <= x,y,z <= n
triples = []
for x in range(1, n+1):
    for y in range(x, n+1):  # y >= x to avoid duplicates
        z = x + y
        if z <= n:
            triples.append((x, y, z))

for (x, y, z) in triples:
    for j in range(c):
        # M[xj] + M[yj] + M[zj] <= 2
        model.Add(M[x-1][j] + M[y-1][j] + M[z-1][j] <= 2)

solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    balls = [0] * n
    for i in range(n):
        for j in range(c):
            if solver.Value(M[i][j]) == 1:
                balls[i] = j + 1
                break
    solution = {
        'balls': balls
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
