from ortools.sat.python import cp_model

def main():
    n = 31
    coins_per_line = 14

    model = cp_model.CpModel()

    # Variables: x[i][j] = 1 if coin placed at row i, column j; else 0
    x = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(model.NewIntVar(0, 1, f'x_{i}_{j}'))
        x.append(row)

    # Constraints:
    # 1. Each row has exactly 14 coins
    for i in range(n):
        model.Add(sum(x[i][j] for j in range(n)) == coins_per_line)

    # 2. Each column has exactly 14 coins
    for j in range(n):
        model.Add(sum(x[i][j] for i in range(n)) == coins_per_line)

    # Objective: minimize sum of squared horizontal distances from main diagonal
    # distance for cell (i,j) is (i - j)^2
    objective_terms = []
    for i in range(n):
        for j in range(n):
            dist_sq = (i - j) * (i - j)
            if dist_sq > 0:
                # multiply by coin presence variable
                objective_terms.append(dist_sq * x[i][j])
            # if dist_sq == 0, no contribution

    model.Minimize(sum(objective_terms))

    # Solve
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        board = []
        for i in range(n):
            row = []
            for j in range(n):
                row.append(solver.Value(x[i][j]))
            board.append(row)

        # Calculate the sum of quadratic horizontal distances
        z = 0
        for i in range(n):
            for j in range(n):
                if board[i][j] == 1:
                    z += (i - j) * (i - j)

        solution = {
            'x': board,
            'z': z
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == '__main__':
    main()
